const MAX_JOBS = 10;      // jobs per run
const MAX_CONTACTS = 3;   // linked contacts per job

const jobs = $('Get Jobs').all().map(i => i.json)
  .filter(j => j.id && ['Will Apply', 'Reaching Out'].includes(String(j.property_decision || '')))
  .slice(0, MAX_JOBS);
const contacts = $('Get Contacts').all().map(i => i.json).filter(c => c.id);
const profileRows = $('Get Profile').all().map(i => i.json).filter(p => p.id);
const existing = $('Get Existing Outreach').all().map(i => i.json).filter(o => o.id);

// Company names (optional: works even if the Get Companies node is missing)
const coName = {};
try {
  $('Get Companies').all().map(i => i.json).filter(c => c.id).forEach(c => { coName[c.id] = c.name || ''; });
} catch (e) {}

const cById = {};
contacts.forEach(c => { cById[c.id] = c; });

// Skip drafts that already exist: job|contact for contacts, job|hm for the hiring-manager message
const done = new Set();
existing.forEach(o => {
  const j = (o.property_job || [])[0];
  const c = (o.property_contact || [])[0];
  if (j && c) done.add(j + '|' + c);
  if (j && !c) done.add(j + '|hm');
});

const g = (p, k) => String(p[k] || '');
const PROFILE = profileRows.slice(0, 12).map(p =>
  '- ' + g(p, 'property_role') + ' at ' + g(p, 'property_employer') + ': ' +
  g(p, 'property_what_i_did').slice(0, 200) +
  (g(p, 'property_result_x') ? ' Result: ' + g(p, 'property_result_x').slice(0, 150) : '')
).join('\n');

// ---------- Prompt for a contact (warm or cold) ----------
const SYSTEM_CONTACT = `You write short LinkedIn messages for a job seeker in Berlin who targets Business Analyst, Project Coordinator and PMO roles.

RULES
- Write in English.
- Maximum 60 words. Count them. No subject line. No emojis. No placeholders such as [Name].
- Start with "Hi <first name>,".
- Use ONLY facts from the CANDIDATE PROFILE and the contact details given. Never invent shared history, projects or numbers.
- Mention the specific job title and company once.
- One clear, small ask. Never ask directly for a job.
- Sound human, warm and direct. No clichés such as "I hope this message finds you well".

TYPE WARM (the candidate knows this person): friendly tone, ask for a 15-minute chat or for their view on the team. Mention a shared connection only if the relationship or notes say so.
TYPE COLD (only the company in common): brief and respectful. Say in one sentence why the candidate's background fits (one real fact from the profile), then ask for a short insight about the team or the role. Keep the candidate's own background to one sentence. Spend the rest on a specific question about the contact's role or team.

Return ONLY the message text.`;

// ---------- Prompt for the hiring manager (name unknown) ----------
const SYSTEM_HM = `You write LinkedIn outreach for a job seeker in Berlin who targets Business Analyst, Project Coordinator and PMO roles. The candidate has just applied for the job below and now writes to the hiring manager or team lead. Their name is not known yet.

RULES
- Write in English. No emojis. No placeholders such as [Name] or [Company].
- Use ONLY facts from the CANDIDATE PROFILE and the job details. Never invent shared history, projects, numbers or tools.
- Mention the job title and the company by name.
- Say in one short sentence that the candidate has applied. Show fit with ONE real result from the profile that matches what the employer needs.
- One clear, small ask, such as a short chat or a pointer on what the team values. Never beg for a job.
- Sound human, direct and respectful. No clichés such as "I hope this message finds you well".

OUTPUT FORMAT (plain text, exactly these two labels)
CONNECTION NOTE:
Starts with "Hi,". STRICT LIMIT: at most 220 characters including spaces, which is about 35 words. Write only two short sentences: (1) you applied for the job at the company, (2) one short fit point and the ask. Stop there. Your counting tends to run over, so keep it clearly shorter than you think necessary.

FOLLOW-UP MESSAGE:
Starts with "Hi,". Between 60 and 80 words, in four short sentences at most.`;

const out = [];
for (const j of jobs) {
  const company = (Array.isArray(j.property_company) && j.property_company[0]) ? (coName[j.property_company[0]] || '') : '';
  const jobBlock =
    'JOB TITLE: ' + (j.name || '') + '\n' +
    'COMPANY: ' + (company || 'see the job description') + '\n' +
    'LOCATION: ' + String(j.property_location || '') + '\n' +
    'WHAT THE EMPLOYER NEEDS:\n' + String(j.property_employer_problems || '').slice(0, 800) + '\n' +
    'JOB DESCRIPTION (start):\n' + String(j.property_raw_job_description || '').slice(0, 1200) + '\n\n';

  // 1. Cold message to the hiring manager, once per job
  if (!done.has(j.id + '|hm')) {
    out.push({ json: {
      job_id: j.id,
      job_title: j.name || '',
      company,
      contact_id: '',
      contact_name: '',
      type: 'Cold',
      kind: 'hiring_manager',
      body: {
        model: 'claude-haiku-5-5',
        max_tokens: 600,
        thinking: { type: 'disabled' },
        system: SYSTEM_HM,
        messages: [{ role: 'user', content: jobBlock + 'CANDIDATE PROFILE:\n' + PROFILE }]
      }
    } });
  }

  // 2. Messages to linked contacts (warm if a relationship is set, otherwise cold)
  const ids = (Array.isArray(j.property_contacts) ? j.property_contacts : []).slice(0, MAX_CONTACTS);
  for (const cid of ids) {
    const c = cById[cid];
    if (!c || done.has(j.id + '|' + cid)) continue;

    const relationship = String(c.property_relationship || '');
    const type = relationship ? 'Warm' : 'Cold';

    const user =
      'TYPE: ' + type + '\n' +
      'CONTACT: ' + (c.name || '') + ', ' + String(c.property_position || '') + '\n' +
      'RELATIONSHIP: ' + (relationship || 'none') + '\n' +
      'NOTES: ' + String(c.property_notes || '').slice(0, 300) + '\n\n' +
      jobBlock + 'CANDIDATE PROFILE:\n' + PROFILE;

    out.push({ json: {
      job_id: j.id,
      job_title: j.name || '',
      company,
      contact_id: cid,
      contact_name: c.name || '',
      type,
      kind: 'contact',
      body: {
        model: 'claude-haiku-5-5',
        max_tokens: 250,
        thinking: { type: 'disabled' },
        system: SYSTEM_CONTACT,
        messages: [{ role: 'user', content: user }]
      }
    } });
  }
}
return out;

const block = ($json.content || []).find(c => c.type === 'text');
let message = (block ? block.text : '').trim();
const src = $('Build Outreach Prompt').item.json;

const isHM = src.kind === 'hiring_manager';

// For the hiring-manager message, check the 300-character limit of LinkedIn connection notes
if (isHM) {
  const m = message.match(/CONNECTION NOTE:\s*([\s\S]*?)\s*FOLLOW-UP MESSAGE:/i);
  if (m && m[1].trim().length > 300) {
    message = 'WARNING: the connection note has ' + m[1].trim().length + ' characters. Shorten it to 300 before sending.\n\n' + message;
  }
}
message = message.slice(0, 1900); // Notion text limit is 2000

const name = isHM
  ? ('Hiring manager - ' + src.job_title + (src.company ? ' (' + src.company + ')' : '')).slice(0, 200)
  : ('Message to ' + src.contact_name + ' - ' + src.job_title).slice(0, 200);

return { json: {
  job_id: src.job_id,
  contact_id: src.contact_id || '',
  name,
  type: src.type,
  message
} };
